        ELSE ("execution_commands"."create_intent"->>'requestCanonicalJson')::jsonb->'payload'->>'nodeAttemptId' = "execution_commands"."create_intent"->'owner'->>'nodeAttemptId' END
      ) IS TRUE);--> statement-breakpoint
